const sessions = new Map();

const tools = [
  {
    name: 'begin_session',
    description: 'Begin a new isolated session identified by session_id.',
    inputSchema: {
      type: 'object',
      properties: {
        session_id: { type: 'string' },
      },
      required: ['session_id'],
      additionalProperties: false,
    },
  },
  {
    name: 'put_value',
    description: 'Store a string value under key, isolated by session_id.',
    inputSchema: {
      type: 'object',
      properties: {
        session_id: { type: 'string' },
        key: { type: 'string' },
        value: { type: 'string' },
      },
      required: ['session_id', 'key', 'value'],
      additionalProperties: false,
    },
  },
  {
    name: 'get_value',
    description: 'Retrieve the value stored under key for the given session_id.',
    inputSchema: {
      type: 'object',
      properties: {
        session_id: { type: 'string' },
        key: { type: 'string' },
      },
      required: ['session_id', 'key'],
      additionalProperties: false,
    },
  },
];

export async function listTools() {
  return tools;
}

function isNonEmptyString(v) {
  return typeof v === 'string' && v.length > 0;
}

export async function callTool(name, args) {
  if (!tools.some(t => t.name === name)) {
    throw new Error('Unknown tool: ' + name);
  }
  // validate no extra arguments
  const allowed = tools.find(t => t.name === name).inputSchema.properties;
  for (const k of Object.keys(args || {})) {
    if (!(k in allowed)) {
      throw new Error('Unexpected argument: ' + k);
    }
  }
  args = args || {};

  if (name === 'begin_session') {
    if (!isNonEmptyString(args.session_id)) {
      throw new Error('session_id must be a non-empty string');
    }
    sessions.set(args.session_id, new Map());
    return { content: [{ type: 'text', text: args.session_id }] };
  }

  if (name === 'put_value') {
    if (!isNonEmptyString(args.session_id)) {
      throw new Error('session_id must be a non-empty string');
    }
    if (!isNonEmptyString(args.key)) {
      throw new Error('key must be a non-empty string');
    }
    if (typeof args.value !== 'string') {
      throw new Error('value must be a string');
    }
    if (!sessions.has(args.session_id)) {
      throw new Error('Session not found: ' + args.session_id);
    }
    sessions.get(args.session_id).set(args.key, args.value);
    return { content: [{ type: 'text', text: args.value }] };
  }

  if (name === 'get_value') {
    if (!isNonEmptyString(args.session_id)) {
      throw new Error('session_id must be a non-empty string');
    }
    if (!isNonEmptyString(args.key)) {
      throw new Error('key must be a non-empty string');
    }
    if (!sessions.has(args.session_id)) {
      throw new Error('Session not found: ' + args.session_id);
    }
    const store = sessions.get(args.session_id);
    if (!store.has(args.key)) {
      throw new Error('Key not found: ' + args.key);
    }
    return { content: [{ type: 'text', text: store.get(args.key) }] };
  }

  throw new Error('Unknown tool: ' + name);
}
